import 'package:flutter/material.dart';

/// The CricScore logo (the app icon artwork, rounded). Generated by
/// `tool/brand/build_icons.mjs` from Design/CricScore_logo.html.
class AppLogo extends StatelessWidget {
  const AppLogo({this.size = 32, super.key});

  final double size;

  static const asset = 'assets/brand/logo.png';

  @override
  Widget build(BuildContext context) => Image.asset(
    asset,
    width: size,
    height: size,
    filterQuality: FilterQuality.medium,
    semanticLabel: 'CricScore logo',
  );
}
